<?php
$zipData = base64_decode('');
file_put_contents('deploy_livewire.zip', $zipData);
$zip = new ZipArchive;
if ($zip->open('deploy_livewire.zip') === TRUE) {
    // Extract directly into the current directory (which is public/)
    $zip->extractTo(__DIR__);
    $zip->close();
    unlink('deploy_livewire.zip');
    echo '<h1>Livewire Assets Fixed!</h1>';
    echo '<p>The missing livewire.js file has been physically installed.</p>';
} else {
    echo '<h1>Error extracting zip</h1>';
}
?>